T("A Suite look, font, minimum height and position for Blizzard dialogs, marked resurrection offers, the item quality written on loot toasts and gold-framed money toasts.", "Visual, fonte, altura mínima e posição da Suite para os diálogos da Blizzard, ofertas de ressurreição marcadas, a qualidade do item escrita nos avisos de saque e avisos de dinheiro com moldura dourada.")
T("A bar cannot attach to itself.", "Uma barra não pode ser anexada a si mesma.")
T("A bar cannot send cooldowns to itself.", "Uma barra não pode enviar recargas para si mesma.")
T("A channel plays a sound kit ID or a sound file (the file wins) for new messages. A burst plays once. Whisper is under Chat tools.", "Um canal toca um kit de som ou arquivo de som (o arquivo tem prioridade) ao receber mensagens. Mensagens em sequência tocam uma vez. Sussurros ficam em Ferramentas de bate-papo.")
T("A cinematic Suite screen with your character while you are AFK. Move or use /afk to return.", "Uma tela cinematográfica da Suite com seu personagem enquanto você está AFK. Mova-se ou use /afk para voltar.")
T("A class in your group can provide this buff.", "Uma classe do seu grupo pode conceder este benefício.")
T("A clean minimap in its own frame: size, shape, border, zoom, Blizzard buttons, an addon button drawer and information texts. Blizzard's minimap buttons keep working.", "Um minimapa limpo em seu próprio quadro: tamanho, forma, borda, zoom, botões da Blizzard, uma gaveta para botões de addons e textos de informação. Os botões do minimapa da Blizzard continuam funcionando.")
T("A click-through surface follows each Blizzard chat window. Blizzard and MSUF Edit Mode keep their normal move and resize controls.", "Uma superfície que não captura cliques acompanha cada janela de bate-papo da Blizzard. O Modo de Edição da Blizzard e o do MSUF mantêm seus controles normais de mover e redimensionar.")
T("A colored plate sits behind the map and its border. Padding extends it beyond the map edge.", "Uma placa colorida fica atrás do mapa e da borda. A margem interna a estende além da borda do mapa.")
T("A compact clock, FPS and latency bar.", "Uma barra compacta de relógio, FPS e latência.")
T("A compact, movable history of your recent successful spells.", "Um histórico compacto e móvel de seus recentes feitiços bem-sucedidos.")
T("A frame-rate readout can sit below the strip or on its own, placed in MSUF Edit Mode. The MSUF Suite FPS key binding shows or hides it for this session, in combat too; a new choice here replaces that session switch.", "Um indicador de quadros pode ficar abaixo da faixa ou à parte, posicionado no modo de edição do MSUF. O atalho de FPS do MSUF Suite o mostra ou oculta nesta sessão, também em combate; uma nova escolha aqui substitui essa opção de sessão.")
T("A group member died", "Um membro do grupo morreu")
T("A movable strip for critical strike, haste, mastery and versatility.", "Uma faixa móvel para ataque crítico, velocidade, maestria e versatilidade.")
T("A movable summary after a Mythic+ run or raid boss kill.", "Um resumo móvel após uma corrida de Mítica+ ou a derrota de um chefe de raide.")
T("A name cannot contain the | character.", "O nome não pode conter o caractere |.")
T("A ring around the mouse pointer that is easy to spot, optionally filled by your global cooldown or cast.", "Um anel bem visível ao redor do ponteiro do mouse, que pode ser preenchido pela sua recarga global ou pelo seu lançamento.")
T("A ring around the mouse pointer that makes it easy to find. Pick its shape, size, color, an optional short trail and a centre dot; No ring keeps only the dot or the progress fill. The camera mode shows ring, dot and trail only while you hold a mouse button down on the game world to turn the camera. The highlight follows the pointer only while something is shown, and it moves nothing while the pointer rests.", "Um anel ao redor do ponteiro do mouse para encontrá-lo com facilidade. Escolha forma, tamanho, cor, um rastro curto e um ponto central; \"Sem anel\" mantém só o ponto ou o preenchimento de progresso. O modo câmera mostra anel, ponto e rastro só enquanto você segura um botão do mouse sobre o mundo do jogo para girar a câmera. O destaque segue o ponteiro só enquanto algo é mostrado e não move nada enquanto o ponteiro está parado.")
T("A secure fishing key with optional rod, lure and a temporary sound profile.\nSet Fishing and Apply fishing lure under Keybindings > MSUF Suite.\nEach action requires your key press; interacting with the bobber stays manual.", "Uma tecla de pesca segura com vara, isca e perfil de som temporário opcionais.\nAtribua Pesca e Aplicar isca de pesca em Teclas > MSUF Suite.\nCada ação exige uma tecla; a interação com a boia continua manual.")
T("A sequence uses one condition rule", "Uma sequência usa uma regra de condições")
T("A small panel beside the Group Finder search results. Its Search filters button saves your difficulty, minimum leader rating, role and dungeon choices in Blizzard's advanced search filter for your next manual search. Use Blizzard's Search button to search. It works on dungeon searches at maximum level, outside combat, and signs you up for nothing.", "Um painel ao lado dos resultados do Localizador de Grupos. O botão Filtros de busca salva dificuldade, pontuação mínima do líder, função e masmorras no filtro avançado da Blizzard para sua próxima busca manual. Use o botão Buscar da Blizzard para pesquisar. Funciona em buscas de masmorras no nível máximo, fora de combate, e não inscreve você em nada.")
T("A small summary sits beside the Character tab of your character sheet and leaves with it. It lists your gear with gem sockets and how many are filled, open ones in amber (click a line to open socketing), the total durability of your gear and, if you like, your PvP item level. Its buttons open the Great Vault and the current expansion page. It updates while the sheet is open, at most once per frame.", "Um pequeno resumo fica ao lado da aba Personagem da sua ficha e some com ela. Lista seu equipamento com engastes e quantos estão preenchidos, os abertos em âmbar (clique em uma linha para engastar), a durabilidade total do equipamento e, se quiser, seu nível de item JxJ. Seus botões abrem o Grande Cofre e a página da expansão atual. Atualiza enquanto a ficha está aberta, no máximo uma vez por quadro.")
T("A snapshot of current keys and loaded Suite action bars. Refresh after changing actions, forms or bindings.", "Retrato das teclas atuais e barras da Suite carregadas. Atualize após mudar ações, formas ou atalhos.")
T("A soft light behind the map, independent of the border and artwork.", "Uma luz suave atrás do mapa, independente da borda e da arte.")
T("A summary with gem sockets, durability, PvP item level and Great Vault and expansion buttons, durability on the model, cropped slot icons and item levels on equipment choices.", "Um resumo com engastes, durabilidade, nível de item JxJ e botões do Grande Cofre e da expansão, durabilidade sobre o modelo, ícones de espaço recortados e níveis de item na escolha de equipamento.")
