T("An empty allow-list includes every quest. Separate quest IDs with spaces or commas. Daily and weekly exclusions leave a quest manual if its frequency cannot be read. Existing profiles keep their previous behavior until you enable an exclusion.", "Uma lista de permissões vazia inclui todas as missões. Separe os IDs de missão com espaços ou vírgulas. As exclusões de diárias e semanais deixam a missão manual se a frequência dela não puder ser lida. Perfis existentes mantêm o comportamento anterior até você ativar uma exclusão.")
