T("Apply a graphics preset once. Balanced changes your general settings and keeps your separate raid settings.\nRaid / Dungeon changes only the separate instance settings and enables them.\nTextures, particle density and outlines stay as you set them; projected textures stay on. Unsupported settings are skipped.\nSharpening, contrast and audio reverb are optional and apply globally.\nYour originals are saved outside profiles. Restore keeps later manual changes. FPS gains depend on your hardware and the scene.", "Aplique uma predefinição gráfica uma única vez. Equilibrado altera as configurações gerais e mantém as configurações separadas de raide.\nRaide / Masmorra altera apenas as configurações separadas de instância e as ativa.\nTexturas, densidade de partículas e contornos ficam como você os definiu; as texturas projetadas permanecem ativadas. Configurações incompatíveis são ignoradas.\nNitidez, contraste e reverberação de áudio são opcionais e se aplicam globalmente.\nOs valores originais são salvos fora dos perfis. A restauração mantém as alterações manuais posteriores. O ganho de FPS depende do hardware e da cena.")
