T("Blizzard yellow and chat system text", "Amarelo da Blizzard e texto do sistema no bate-papo")
T("Blizzard's Cooldown Manager stops completely. While your MSUF frames follow its bars, MSUF keeps it running invisibly.", "O Gerenciador de Recargas da Blizzard para completamente. Enquanto seus quadros do MSUF seguirem as barras dele, o MSUF o mantém funcionando de forma invisível.")
T("Blizzard's aggro, target, focus and soft target signals.", "Sinais da Blizzard de aggro, alvo, foco e alvo suave.")
T("Blizzard's bars keep running, invisible, so frames that other addons attach to them stay in place.", "As barras da Blizzard continuam funcionando, invisíveis, para que quadros que outros addons anexam a elas fiquem no lugar.")
T("Blizzard's combined switch for pets, guardians and totems. The separate choices set each kind on its own.", "Opção conjunta da Blizzard para ajudantes, guardiões e totens. As opções separadas controlam cada tipo.")
