T("Blizzard's own nameplate options. Keep Blizzard setting changes nothing; other choices go back to Blizzard's value when the skin turns off.", "Opções de placas da própria Blizzard. Manter configuração da Blizzard não muda nada; as outras escolhas voltam ao valor da Blizzard quando a skin é desligada.")
