T("Center keeps the whole visible cooldown row centered as icons appear or disappear. Enable Keep first icon centered for alternating growth around the first icon. Buff icons then keep fixed places, with gaps for inactive buffs. Attach the bar to another bar or to your player frame; Gap controls the space between them.", "Centro mantém toda a linha visível de recargas centralizada quando os ícones aparecem ou desaparecem. Ative Manter o primeiro ícone centralizado para adicionar os próximos alternadamente ao redor do primeiro. Os ícones de benefícios mantêm posições fixas, com espaços para benefícios inativos. Ancore a barra a outra barra ou ao quadro do jogador; Espaçamento controla a distância entre eles.")
