T("Choose Clean Modern, Midnight Blue, MSUF Forever Glass, Midnight Dark or Class Style for Skinning and enabled Suite modules. Modules enabled later inherit it.", "Escolha Moderno limpo, Midnight Blue, Vidro MSUF Forever, Midnight Dark ou Estilo de classe para a skin e os módulos ativos da Suite. Módulos ativados depois o herdam.")
T("Choose Clean Modern, Midnight Blue, Midnight Dark, MSUF Forever or Class Style. This changes only the bag window colors and opacity; item slots and Blizzard bag actions remain intact.", "Escolha Moderno limpo, Midnight Blue, Midnight Dark, MSUF Forever ou Estilo de classe. Isso altera apenas cores e opacidade da janela das bolsas; espaços e ações da Blizzard permanecem intactos.")
T("Choose Clean Modern, Midnight Blue, neutral Midnight Dark glass or MSUF Forever's dark gold frame. All use MSUF's bar texture and font. Turn the 20 XP divisions on or off. The lower line can show session gain, XP per hour and time to level. Move or resize the bar in MSUF Edit Mode; its popup edits X, Y, width, height and scale. Hover for exact values. A session survives /reload and starts fresh on the next login.", "Escolha Clean Modern, Midnight Blue, vidro neutro Midnight Dark ou moldura dourada escura MSUF Forever. Todos usam a textura e a fonte da barra de MSUF. Ative ou desative as divisões de 20 XP. A linha inferior pode mostrar o ganho da sessão, XP por hora e tempo para nivelar. Mova ou redimensione a barra no modo de edição MSUF; seu pop-up edita X, Y, largura, altura e escala. Passe o mouse para valores exatos. Uma sessão sobrevive /reload e começa do zero no próximo login.")
T("Choose Craft quantity to change how many times you plan to craft this tracked recipe.", "Escolha Quantidade de fabricação para mudar quantas vezes pretende criar esta receita rastreada.")
T("Choose Custom layout to set the order of total, per-second and percent values, then pick spaces, brackets or a separator. The percent switch controls main rows; breakdown rows show available shares. Unavailable shares are omitted. Primary means per second for DPS/HPS and total for other meters. Text settings also apply to headers, details and the floating timer. Slug uses WoW's crisp font renderer with an outline and no shadow. Protected values show without a percentage until combat ends.", "Escolha Layout personalizado para definir a ordem dos valores total, por segundo e porcentagem e, depois, escolha espaços, colchetes ou um separador. A opção de porcentagem controla as linhas principais; as linhas de detalhamento mostram as parcelas disponíveis. Parcelas indisponíveis são omitidas. Primário significa por segundo para DPS/HPS e total para os outros medidores. As configurações de texto também valem para cabeçalhos, detalhes e o cronômetro flutuante. Slug usa o renderizador de fonte nítido do WoW, com contorno e sem sombra. Valores protegidos aparecem sem porcentagem até o combate terminar.")
T("Choose DoTs for this specialization. Disabled entries keep their position.", "Escolha DoTs para esta especialização. As entradas desativadas mantêm sua posição.")
