T("Choose an MSUF font, outline, shadow and Smooth, Sharp or Slug rendering. Slug has no shadow. Label, value and warning colors are separate.", "Escolha uma fonte do MSUF, contorno, sombra e renderização Suave, Nítida ou Slug. Slug não tem sombra. As cores de rótulo, valor e aviso são separadas.")
T("Choose an MSUF or SharedMedia font and bar texture. Font size, outline, shadow, Smooth/Sharp/Slug rendering, bar height and spacing update the HUD immediately. Slug has no shadow.", "Escolha uma fonte e uma textura de barra do MSUF ou do SharedMedia. Tamanho da fonte, contorno, sombra, renderização Suave/Nítida/Slug, altura da barra e espaçamento atualizam o HUD imediatamente. Slug não tem sombra.")
