T("Choose broad UI families. Dedicated secure behavior and semantic artwork remain untouched.", "Escolha grandes famílias da interface. O comportamento protegido dedicado e a arte com significado permanecem intocados.")
T("Choose broker names and discovered currency IDs per place. Select your current-season crest currencies from the native currency list; saved currency selections work after login without visiting an upgrade NPC. Selection order and separator control the crest block. Observed upgrade stages remain available as an alternative after selecting an upgrade item this login. Hearthstone actions require a deliberate click.", "Escolha nomes de broker e IDs de moedas descobertas por posição. Selecione suas moedas de brasões da temporada atual na lista nativa; as seleções salvas funcionam após entrar no jogo sem visitar um PNJ de aprimoramento. A ordem de seleção e o separador controlam o bloco de brasões. As etapas de aprimoramento observadas continuam disponíveis como alternativa após selecionar um item para aprimorar nesta sessão. As ações de Pedra de Regresso exigem um clique intencional.")
T("Choose buffs and consumables to track.", "Escolha os bônus e consumíveis que deseja acompanhar.")
T("Choose clean window controls and a complete Micro Bar style, then tune individual artwork only when needed.", "Escolha controles de janela limpos e um estilo completo de microbarra; ajuste artes individuais só quando necessário.")
