T("Docked timers follow the selected window and hide with it. Positive horizontal offsets move right; positive vertical offsets move up.", "Cronômetros acoplados seguem a janela escolhida e se ocultam com ela. Valores horizontais positivos movem à direita; verticais positivos, para cima.")
