T("Double", "Duplo")
T("Double-click a search result to open Blizzard's application dialog. With submit on double-click, the second click also signs up with the roles already chosen in that dialog; hold Shift to review it instead. A saved note can appear beside the dialog for copying; it is stored when you finish editing.", "Clique duas vezes em um resultado da busca para abrir a janela de inscrição da Blizzard. Com o envio por clique duplo, o segundo clique também faz a inscrição com as funções já escolhidas nessa janela; segure Shift para revisá-la em vez disso. Uma nota salva pode aparecer ao lado da janela para ser copiada; ela é salva quando você termina de editar.")
T("Double-click a search result to open Blizzard's normal application dialog.", "Clique duas vezes em um resultado da busca para abrir a janela normal de candidatura da Blizzard.")
T("Down", "Para baixo")
T("Draft saved", "Rascunho salvo")
T("Drag a window by its top edge; drag the bottom-right corner to scale it. The top-right minus button collapses compatible windows to a restore tab. Bags and protected windows keep their native behavior.", "Arraste uma janela pela borda superior; arraste o canto inferior direito para mudar a escala. O botão de menos no canto superior direito recolhe janelas compatíveis em uma aba de restauração. Bolsas e janelas protegidas mantêm o comportamento nativo.")
T("Drag announcements in MSUF Edit Mode, or set their timing, scale and exact position here.", "Arraste os anúncios no Modo de Edição do MSUF ou defina aqui o tempo, a escala e a posição exata.")
T("Drag or use arrows to move; Shift: 5, Ctrl: 10.", "Arraste ou use as setas para mover; Shift: 5, Ctrl: 10.")
T("Drag or use arrows to move; click for settings.", "Arraste ou use as setas para mover; clique para ver as configurações.")
T("Drag the bag title to move it; click for options.", "Arraste o título da bolsa para movê-la; clique para ver opções.")
T("Drag the bar's edge to move it on screen.", "Arraste a borda da barra para movê-la na tela.")
T("Drag the reagent bag title while it is open to move it independently. Click the title for bag options. Reset its position in MSUF Edit Mode to follow Blizzard's normal bag layout again.", "Arraste o título da bolsa de reagentes enquanto ela estiver aberta para movê-la separadamente. Clique no título para ver as opções de bolsa. Redefina a posição dela no Modo de Edição do MSUF para voltar a seguir o layout normal de bolsas da Blizzard.")
T("Drag the result card in MSUF Edit Mode, or set its screen anchor, width, scale and position here.", "Arraste o cartão de resultados no Modo de Edição do MSUF ou defina aqui a âncora, largura, escala e posição.")
T("Drag the title of an open bag to move it. Click the title for bag options. Each bag keeps its own position. Blizzard shows your current gold on the right; the optional Session value on the left shows the change since login and survives /reload. Adjust the combined bag size here or in its MSUF Edit Mode popup. Reset position in Edit Mode returns the window to Blizzard's normal anchor.", "Arraste o título de uma bolsa aberta para movê-la. Clique no título para ver as opções de bolsa. Cada bolsa mantém sua própria posição. A Blizzard mostra seu ouro atual à direita; o valor opcional Sessão, à esquerda, mostra a variação desde o login e sobrevive ao /reload. Ajuste o tamanho da bolsa combinada aqui ou no popup dela no Modo de Edição do MSUF. Redefinir posição no Modo de Edição devolve a janela à âncora normal da Blizzard.")
