T("Drop an item here to add it without moving it.", "Solte um item aqui para adicioná-lo sem movê-lo.")
T("Drop an item onto Pinned items in the category sidebar to keep it at the top of every view. Recent items lists up to 200 item types this character received, also across logins; each leaves the list once it is older than the hours set here, and Clear recent items empties it sooner. Neither action moves or deletes an item.", "Solte um item em Itens fixados na barra lateral para mantê-lo no topo de todas as visualizações. Itens recentes lista até 200 tipos de itens que este personagem recebeu, também entre logins; cada um sai da lista quando passa das horas definidas aqui, e Limpar itens recentes a esvazia antes. Nenhuma dessas ações move ou exclui itens.")
T("Dropdown and previous/next arrows", "Setas de menus suspensos e de anterior/próximo")
T("Drops this bar's own order and the spells and items you added to it, for this specialization. Spells you removed stay hidden: Show removed spells brings them back. You can undo it.", "Descarta a ordem própria desta barra e os feitiços e itens que você adicionou a ela, para esta especialização. Os feitiços que você removeu continuam ocultos: Mostrar feitiços removidos os traz de volta. Você pode desfazer isso.")
