T("Each phrase may contain up to 80 characters.", "Cada frase pode conter até 80 caracteres.")
T("Each response is its own switch and none acts in combat. A summon that skips a starting area, and a resurrection during a boss encounter or while Blizzard makes you wait, stay yours. Party invite declines never touch friends, Battle.net friends or guild members, and invites that ask for a role or start a quest session stay yours. A chat line can report each response.", "Cada resposta tem sua própria opção e nenhuma age em combate. Evocações que pulam uma área inicial e ressurreições durante chefes ou esperas impostas pela Blizzard continuam manuais. Recusas de convites de grupo nunca afetam amigos, amigos do Battle.net ou membros da guilda; convites com função ou sessão de missões continuam manuais. Uma mensagem pode informar cada resposta.")
T("Each specialization keeps its own bar layout: positions, attachments, growth, rows, spacing and sizes. Until it has its own, it uses the current one.", "Cada especialização mantém o próprio layout das barras: posições, ancoragens, crescimento, linhas, espaçamento e tamanhos. Enquanto não tiver um próprio, usa o atual.")
T("Each window keeps its own meter, fight, size and visibility rules. Drag the header or use MSUF Edit Mode to move it.", "Cada janela mantém suas próprias regras de medidor, luta, tamanho e visibilidade. Arraste o cabeçalho ou use o Modo de Edição do MSUF para movê-la.")
