T("Enter the cast spell's name or ID. Leave empty for automatic spell matching. Timers start only from readable player cast events.", "Insira o nome ou ID do feitiço lançado. Deixe vazio para associação automática. Os temporizadores só começam com eventos de lançamento legíveis do jogador.")
T("Enter up to 200 item IDs. A button appears only at a merchant and previews eligible stacks; clicking it opens a confirmation. The helper checks item identity, quality, value, quest status and bag position again before requesting sales. Equippable items require a separate opt-in.", "Insira até 200 IDs de itens. Um botão aparece somente no comerciante e mostra as pilhas elegíveis; ao clicar, você abre uma confirmação. A função verifica novamente o ID, a qualidade, o valor, o estado de missão e a posição na bolsa antes de solicitar a venda. Itens equipáveis exigem uma autorização separada.")
T("Enter up to eight spell IDs for movement abilities. When movement begins, the first known, ready and usable spell appears briefly; a shared 20-second cooldown limits notices. Empty IDs do no work. MSUF Edit Mode moves the cue.", "Insira até oito IDs de feitiço para habilidades de movimento. Quando o movimento começa, o primeiro feitiço conhecido, pronto e utilizável aparece brevemente; um tempo de espera compartilhado de 20 segundos limita os avisos. IDs vazios não funcionam. MSUF O modo de edição move o cue.")
