T("Every spell of this bar, unlearned ones included. On a buff bar, Add spells offers received buffs such as Power Infusion and Innervate; Buff on me also accepts a buff aura ID or resolvable name and tracks that ID from any caster. With Show missing buffs off, only active buffs appear. The preview edits entries too: click for options, drag to reorder or onto a bar above, middle-click to remove (with undo). Removed spells stay under Add spells. Lists are kept per specialization.", "Todos os feitiços desta barra, incluindo os não aprendidos. Em uma barra de bônus, Adicionar feitiços oferece bônus recebidos, como Infusão de Poder e Estimular; Bônus em mim também aceita um ID de aura de bônus ou um nome reconhecível e rastreia esse ID de qualquer lançador. Com Mostrar bônus ausentes desativado, apenas bônus ativos aparecem. A prévia também edita entradas: clique para ver opções, arraste para reordenar ou para uma barra acima, clique do meio para remover (com desfazer). Feitiços removidos ficam em Adicionar feitiços. As listas são mantidas por especialização.")
