T("Fonts, outlines, shadows and Smooth/Sharp/Slug rendering for keybinds, macro names, counts and cooldown numbers. Sizes are set per bar below. Slug has no shadow.", "Fontes, contornos, sombras e renderização Suave/Nítida/Slug para atalhos, nomes de macro, contagens e números de recarga. Os tamanhos são definidos por barra abaixo. Slug não tem sombra.")
T("Food and drink", "Comida e bebida")
T("Food buff (Well Fed)", "Bônus de comida (Bem Alimentado)")
T("Food to eat first (item ID)", "Comida a comer primeiro (ID do item)")
T("For Warlocks: show Burning Rush only while its aura is active in combat. Blizzard's native aura container follows the aura; Suite does not scan auras. MSUF Edit Mode shows a sample and moves the cue.", "Para Bruxos: mostre Impulso Ardente apenas enquanto sua aura estiver ativa em combate. O contêiner nativo de auras da Blizzard acompanha a aura; a Suite não examina auras. O Modo de Edição do MSUF mostra um exemplo e permite mover o aviso.")
T("Forces", "Forças")
T("Forever Suite layout with Antique Map and optional parchment Skin.", "Layout Suite Forever com Antique Map e Skin de pergaminho opcional.")
T("Forever artwork", "Arte Forever")
T("Forever factory profile unavailable", "Perfil de fábrica Forever indisponível")
T("Forever only. A secure fishing key that casts Fishing, equipping the rod you choose first, and a second key that applies the lure you choose. Set both under Keybindings > MSUF Suite. Each action needs your key press; interacting with the bobber stays manual. The optional sound profile sets your fishing volumes while you cast and restores them afterwards.", "Somente Forever. Uma tecla segura equipa a vara escolhida e lança Pesca; outra aplica a isca escolhida. Defina ambas em Teclas de atalho > MSUF Suite. Cada ação exige pressionar a tecla; interagir com a boia continua manual. O perfil de som opcional aplica os volumes de pesca durante o lançamento e restaura depois.")
T("Forever only. Route times are learned from completed flight-master journeys and kept in this profile. A first journey has no invented estimate. Early landing does not overwrite a full-route time. Intermediate stops come from the native taxi map; its tooltip can preview the route. Land at next stop requests the next available landing point.", "Apenas Forever. Aprende tempos de viagens completas e os guarda neste perfil. A primeira viagem não recebe estimativa inventada. Pousar antes não sobrescreve o tempo completo. Paradas vêm do mapa nativo de voo, cuja dica pode exibir a rota. «Pousar na próxima parada» solicita o próximo ponto disponível.")
T("Forever only. When a quest offers a choice of rewards, the one with the highest vendor value, counting its stack size, is marked. Nothing is selected or turned in for you.", "Somente Forever. Quando uma missão oferece escolha de recompensas, marca a de maior preço de venda, considerando a quantidade na pilha. Nada é selecionado nem entregue automaticamente.")
