T("Frames join aligned bars; detached bars keep separate frames. Effects are static. Threshold marks a fixed percentage. Preview switches apply live.", "A moldura externa une as barras de vida e lançamento; sem lançamento visível, envolve apenas a vida. Sombra e brilho são estáticos. As texturas mantêm as cores de vida e auras. A linha marca uma porcentagem fixa, não um alerta de execução. Ative cada função nas camadas da prévia. Barras separadas ou de tamanhos diferentes mantêm molduras individuais.")
