T("Friendly player display chooses Blizzard's setting, names for all friendly players, names for party / raid only, or health bars. Names only hides Blizzard bars, casts and auras for friendly players; it does not change NPC or enemy plates. Group / outsider in the preview only changes the sample. Blizzard can forbid changes to friendly plates in instances; those frames stay under Blizzard's control.", "Exibição de jogadores aliados escolhe a configuração da Blizzard, nomes para todos os jogadores aliados, nomes apenas para grupo / raide ou barras de vida. Apenas nomes oculta as barras, os lançamentos e as auras da Blizzard para jogadores aliados; não altera placas de PNJs nem inimigas. Grupo / fora do grupo na prévia muda apenas o exemplo. A Blizzard pode proibir alterações em placas aliadas em instâncias; esses quadros ficam sob o controle da Blizzard.")
