T("Gives Blizzard's player buffs and debuffs the icon skins you chose on the Icon Skins page, at Blizzard's own size and layout. The skins are painted once, out of combat, and no code runs on aura updates. While Player aura layout is on, it paints the buttons itself and this switch waits.", "Aplica aos benefícios e penalidades do jogador da Blizzard as aparências escolhidas na página de ícones, mantendo tamanho e disposição. A aparência é aplicada uma vez fora de combate; nenhuma rotina roda nas atualizações de auras. Enquanto a disposição de auras do jogador estiver ativa, ela própria pinta os botões e esta opção espera.")
T("Gives this bar's place, attachment, growth, rows and sizes to your other specializations. You can undo it.", "Aplica posição, vínculo, crescimento, linhas e tamanhos desta barra às outras especializações. Você pode desfazer.")
