T("Hide Blizzard's main tooltip in combat, in instances, or for selected item, spell and unit tooltips. MSUF unit and group frame tooltips keep their own visibility settings; aura tooltips keep their Show Tooltip switches. Each choice works independently. A hidden tooltip turns fully transparent, so Blizzard keeps handling it as usual.", "Oculte a dica principal da Blizzard em combate, em instâncias ou para itens, feitiços e unidades selecionados. As dicas dos quadros de unidade e grupo do MSUF mantêm suas próprias configurações de visibilidade; as dicas de auras mantêm suas opções Mostrar dica. Cada escolha funciona de forma independente. Uma dica oculta fica totalmente transparente, e a Blizzard continua a tratá-la normalmente.")
