T("Hold Alt to see the ID of an item, spell, creature, quest, currency or temporary weapon enchant on its tooltip, or press Alt while the tooltip is open; the IDs stay until the tooltip is built again. Spell icon IDs and Blizzard's account character currency data are optional, and that data joins an open tooltip when it arrives. No ID or quantity appears when the client keeps it private.", "Segure Alt para ver o ID de um item, feitiço, criatura, missão, moeda ou encantamento temporário de arma na dica, ou pressione Alt com a dica aberta; os IDs ficam até a dica ser montada de novo. IDs de ícone de feitiço e os dados de moeda dos seus outros personagens da Blizzard são opcionais, e esses dados entram em uma dica aberta quando chegam. Nenhum ID ou quantidade aparece quando o cliente os mantém privados.")
T("Hold Alt to show item, spell, creature, quest, currency and temporary weapon enchant IDs on the main tooltip.", "Segure Alt para mostrar IDs de item, feitiço, criatura, missão, moeda e encantamento de arma temporária na dica de ferramenta principal.")
