T("Keep Blizzard grid, or choose one Suite grid, physical bag groups or categories. Use Edit categories in the bag window to create, rename, reorder or disable your categories; drop items onto a sidebar category to assign them. Sort items by orders every Suite view; Name keeps the order each view has always had. Click a category header to hide or show its items. The footer counts free slots, and Mark items that beat what you wear puts a small arrow on equipment that beats what you wear in its slot. Scroll or use Previous and Next for larger inventories; in combat every slot is shown at once. Combined stack counts are visual only; physical stacks are always restored at the bank, guild bank, mail, trade, auction house and merchant.", "Mantenha a grade da Blizzard ou escolha uma grade Suite, grupos por bolsa física ou categorias. Use Editar categorias na bolsa para criar, renomear, reordenar ou desativar categorias; arraste itens para uma categoria lateral para atribuí-los. Ordenar itens por organiza todas as visualizações Suite; Nome mantém a ordem tradicional de cada uma. Clique no cabeçalho para ocultar ou mostrar os itens. O rodapé conta os espaços livres, e Marcar itens melhores que os equipados adiciona uma pequena seta ao equipamento melhor para aquele espaço. Use a rolagem ou Anterior e Próximo em inventários maiores; em combate todos os espaços aparecem juntos. Contagens combinadas são apenas visuais; as pilhas físicas sempre voltam no banco, banco da guilda, correio, troca, leilão e vendedor.")
