T("Lists carried gem types beside Blizzard's socket window. Inspect each gem with its normal bag tooltip and confirm compatibility in the native socket window before applying it.", "Lista os tipos de gemas nas bolsas ao lado da janela de engaste da Blizzard. Inspecione cada gema pela dica normal da bolsa e confirme a compatibilidade na janela de engaste antes de aplicá-la.")
T("Lists the casts of attackable enemy nameplates while you are in a five-player dungeon, oldest first; the game runs each bar and timer. The game keeps spell, target, marker and interrupt details hidden from addons, so casts are never sorted or filtered by them: fading or hiding uses the game's important-spell flag (a hidden cast keeps its place in the list), raid markers sit on the spell icon, and the ready mark, an edge stripe or the whole bar, shows on interruptible casts while your interrupt is off cooldown. Dimming checks four times a second whether your interrupt reaches each listed enemy; a cast it cannot check stays bright. The interrupt is found from your talents and pet unless you enter a spell ID. MSUF Edit Mode shows sample casts for placing the list.", "Lista os lançamentos dos inimigos atacáveis com placa de identificação enquanto você está numa masmorra para cinco jogadores, do mais antigo ao mais recente; o jogo conduz cada barra e cronômetro. O jogo oculta dos addons o feitiço, o alvo, o marcador e se é possível interromper, por isso os lançamentos nunca são ordenados nem filtrados por eles: esmaecer ou ocultar usa a marcação de feitiço importante do jogo (um lançamento oculto mantém seu lugar na lista), os marcadores de raide ficam no ícone do feitiço e a marca de pronto, uma faixa na borda ou a barra inteira, aparece nos lançamentos interrompíveis enquanto sua interrupção não está em recarga. O escurecimento verifica quatro vezes por segundo se sua interrupção alcança cada inimigo listado; um lançamento que não pode ser verificado continua claro. A interrupção é detectada pelos seus talentos e mascote, a menos que você informe um ID de feitiço. O modo de edição do MSUF mostra lançamentos de exemplo para posicionar a lista.")
T("Lists the casts of enemy nameplates in five-player dungeons, oldest first, with timers the game runs.", "Lista os lançamentos das placas de identificação inimigas em masmorras para cinco jogadores, do mais antigo ao mais recente, com cronômetros conduzidos pelo jogo.")
