T("Mainline covers Rogue poisons, this season's flasks, augment runes and weapon oils, and the Well Fed food buff. Each category clicks the first matching item in your bags; an item you enter for it is tried first. Food is found in your bags by the game's eating spells: the food you enter comes first, then the newest one. With the gray reminder on, a category with nothing left stays visible without a click action. Assassination prefers Deadly Poison; Outlaw and Subtlety prefer Instant Poison. Dragon-Tempered Blades allows two poisons per category. Oils target equipped weapons; known Shaman or Paladin imbues suppress automatic oils.", "Mainline cobre os venenos de ladino, os frascos, runas de aprimoramento e óleos de arma desta temporada e o bônus de comida Bem Alimentado. Cada categoria usa ao clicar o primeiro item adequado das bolsas; um item que você informar para ela é tentado primeiro. A comida é encontrada nas bolsas pelos feitiços de comer do jogo: primeiro a que você informar, depois a mais recente. Com o lembrete cinza, uma categoria esgotada continua visível sem ação de clique. Assassinato prefere Veneno Mortal; Fora da Lei e Subterfúgio preferem Veneno Instantâneo. Lâminas Temperadas por Dragões permite dois venenos por categoria. Os óleos vão para as armas equipadas; encantamentos conhecidos de xamã ou paladino suprimem os óleos automáticos.")
