T("Mapko uses Modern plates, Medium size and the same bar dimensions on Retail and Forever. Guild names and titles also affect names in the world. Bind Toggle friendly NPC nameplates under MSUF Suite in Blizzard Key Bindings. Import protection keeps your current nameplates when importing a full Suite profile; explicit nameplate imports still replace them.", "Mapko usa placas modernas, tamanho médio e as mesmas dimensões no Retail e Forever. Nomes de guilda e títulos também afetam os nomes no mundo. Configure Alternar placas de PNJs aliados em MSUF Suite nas teclas da Blizzard. A proteção de importação preserva suas placas ao importar um perfil completo do Suite; importações específicas de placas ainda as substituem.")
