T("Only a cooldown bar can take excess cooldowns.", "Somente uma barra de recargas pode receber as excedentes.")
T("Only containers newly acquired after enabling this helper are opened. It waits for combat to end, opens one at a time, and leaves them to you while you hold Shift or a loot window or a window that gives item use another meaning is open: merchant, bank, guild bank, mail, trade, auction house, scrapper, socket, upgrade and similar. Warbound containers stay unopened unless you allow them; profiles that used this helper before keep opening them. Midnight Artisan payouts can wait while your Shard of Dundun is capped.", "Somente recipientes obtidos após ativar esta função são abertos. Ela espera o fim do combate, abre um de cada vez e os deixa com você enquanto você mantém Shift pressionado ou há uma janela de saque ou uma janela que dá outro sentido ao uso de um item aberta: comerciante, banco, banco da guilda, correio, troca, casa de leilões, sucateador, engaste, aprimoramento e semelhantes. Recipientes do Bando de Guerra continuam fechados, a menos que você os permita; perfis que já usavam esta função continuam abrindo-os. Pagamentos de artesão de Midnight podem esperar enquanto seus Estilhaços de Dundun estiverem no limite.")
T("Only in an active Delve and outside combat: if the player choice has exactly one enabled spell option, one button and no confirmation, MSUF selects it once. Other choices remain manual.", "Somente em uma Imersão ativa e fora de combate: se a escolha do jogador tiver exatamente uma opção de feitiço habilitada, um botão e nenhuma confirmação, o MSUF a seleciona uma vez. Outras escolhas continuam manuais.")
T("Only inside instances", "Apenas dentro de instâncias")
