T("Open your equipment window beside an item upgrade merchant and close only the window MSUF opened.", "Abra a janela do seu equipamento ao lado de um comerciante de atualização de item e feche apenas a janela MSUF aberta.")
T("Opens your character window, on the tab you used last, when an item upgrade merchant opens. It closes only a window this helper opened and waits for the end of combat to open or close it.", "Abre sua janela de personagem, na última aba usada, quando um comerciante de aprimoramento de itens é aberto. Fecha somente uma janela aberta por esta função e espera o fim do combate para abri-la ou fechá-la.")
T("Optional Blizzard settings for chat, map, sound and low-health or alternate screen flashes. MSUF restores the previous value when you turn a choice or this helper off. Changes you make yourself in Blizzard settings while this helper runs are respected.", "Configurações opcionais de Blizzard para bate-papo, mapa, som e falta de saúde ou flashes de tela alternativos. MSUF restaura o valor anterior quando você desativa uma opção ou desativa este auxiliar. As alterações feitas nas configurações de Blizzard enquanto este auxiliar é executado são respeitadas.")
T("Optional artwork and spacing controls. Use MSUF Edit Mode for position, nudging, reset, undo and redo.", "Controles opcionais de arte e espaçamento. Use o Modo de Edição do MSUF para posição, ajuste fino, redefinição, desfazer e refazer.")
