T("Remembers your characters that you visit while this helper is on and lists them beside the mail window. Click a name to fill the recipient, right-click to hide or restore it, and search by name. Only characters on your current or connected realms are listed. Sending stays manual.", "Lembra seus personagens visitados com este auxiliar ativo e os lista ao lado do correio. Clique no nome para preencher o destinatário, clique com o botão direito para ocultar ou restaurar e busque por nome. Apenas personagens do reino atual ou de reinos conectados aparecem. O envio continua manual.")
