T("Show weather as text, an icon, or both. Choose Blizzard icons or original Forever artwork. The tooltip keeps the weather name when only the icon is shown.", "Mostra o clima como texto, ícone ou ambos. Escolha ícones da Blizzard ou a arte original Forever. A dica mantém o nome do clima quando apenas o ícone é exibido.")
