T("Show your Bloodlust exhaustion or ready state while grouped.", "Mostre sua exaustão de Bloodlust ou estado de prontidão enquanto estiver agrupado.")
T("Show your owned item count, including bank and Warband bank, on item tooltips.", "Mostre a contagem de itens que você possui, incluindo banco e banco de Warband, nas dicas de itens.")
T("Show your selected loot specialization in the Great Vault window.", "Mostra sua especialização de saque selecionada na janela do Grande Cofre.")
T("Show zone", "Mostrar zona")
T("Show, hide and customize Blizzard's player buff and debuff bars.", "Mostre, oculte e personalize as barras de benefícios e penalidades do jogador da Blizzard.")
T("Shown value", "Valor exibido")
T("Shown windows: %d. Raise the number of windows to show this one.", "Janelas exibidas: %d. Aumente o número de janelas para mostrar esta.")
T("Shows Blizzard's shared battle resurrection charges in an active Mythic+ run or raid encounter. The icon counts down to the next charge using Blizzard's cooldown display. Hidden when the shared pool is unavailable. MSUF Edit Mode previews the display and edits X, Y, width, height and scale.", "Mostra as cargas compartilhadas de ressurreição em combate da Blizzard em uma Mítica+ ativa ou em um encontro de raide. O ícone faz a contagem regressiva até a próxima carga usando a exibição de recarga da Blizzard. Fica oculto quando o conjunto compartilhado está indisponível. O Modo de Edição do MSUF mostra uma prévia da exibição e edita X, Y, largura, altura e escala.")
T("Shows an approximate range to your current target from the game's range checks of spells you know; values include the target's hitbox, and dashes mean that no known spell can tell. Write the text with {range} and {unit}. The estimate can sit below the target frame, following it when the frame moves, or anywhere on screen; MSUF Edit Mode moves both placements.", "Mostra uma distância aproximada até seu alvo atual a partir das verificações de alcance do jogo para os feitiços que você conhece; os valores incluem a área de acerto do alvo, e traços indicam que nenhum feitiço conhecido consegue determinar. Escreva o texto com {range} e {unit}. A estimativa pode ficar abaixo do quadro do alvo, acompanhando-o quando o quadro se move, ou em qualquer lugar da tela; o modo de edição do MSUF move as duas posições.")
T("Shows each ready interrupt with the bar's glow style while the target's cast can be interrupted. Requires per-interrupt readiness from MSUF.", "Exibe cada interrupção disponível com o estilo de brilho da barra enquanto o lançamento do alvo puder ser interrompido. Requer dados de disponibilidade de cada interrupção do MSUF.")
T("Shows incoming damage and healing for you or your vehicle. Blizzard's own combat text is hidden while enabled and restored when disabled. Move the display in MSUF Edit Mode. During heavy bursts the oldest of the visible messages is replaced. The game may keep amounts private, so messages are never combined or filtered by their value.", "Mostra o dano e a cura recebidos por você ou seu veículo. O texto de combate da Blizzard fica oculto enquanto o módulo está ativo e volta ao desativá-lo. Mova a exibição no modo de edição do MSUF. Quando há muitas mensagens, a mais antiga visível é substituída. O jogo pode manter os valores privados; as mensagens nunca são somadas nem filtradas por sua quantidade.")
T("Shows item levels on merchant equipment when Blizzard has loaded its item data. Buyback items and items without an item level stay unchanged.", "Mostra os níveis de item nos equipamentos do comerciante quando a Blizzard carrega os dados dos itens. Itens de recompra e itens sem nível de item permanecem inalterados.")
T("Shows the active potion buff. Instant healing and mana potions do not leave a buff.", "Mostra o efeito benéfico ativo da poção. Poções de vida e mana instantâneas não deixam um efeito benéfico.")
T("Shows the current loot specialization when you open the Great Vault. Updates if you change loot specialization while the window is open.", "Mostra a especialização de saque atual quando você abre o Grande Cofre. Atualiza se você mudar a especialização de saque com a janela aberta.")
T("Shows the lowest equipped durability below your chosen threshold, outside combat. MSUF Edit Mode shows a sample even when your gear is repaired. Its popup edits X, Y, width, height and scale.", "Mostra, fora de combate, a menor durabilidade equipada abaixo do limite escolhido. O Modo de Edição do MSUF mostra um exemplo mesmo com seu equipamento reparado. O popup edita X, Y, largura, altura e escala.")
T("Shows the number you own, including your bank and Warband bank, when the item tooltip has a public item ID. Optionally separate storage locations. Empty counts are omitted.", "Mostra o número que você possui, incluindo seu banco e banco de Warband, quando a dica do item tem um ID de item público. Opcionalmente, separar locais de armazenamento. As contagens vazias são omitidas.")
T("Shows the share of the keystone's enemy forces that an enemy gives, while a Mythic+ keystone is running and Blizzard shows no such line itself.", "Mostra a porcentagem de forças inimigas que um inimigo concede durante uma pedra-chave Mítica+, quando a Blizzard ainda não mostra essa informação.")
T("Shows the spell's icon in the middle of the screen when its cooldown ends, even while this bar is hidden. Its size, place and time are in General.", "Mostra o ícone do feitiço no centro da tela ao terminar sua recarga, mesmo com esta barra oculta. Tamanho, posição e duração ficam em Geral.")
T("Shows the total durability of your gear on the character model, moved by the two offsets, and crops the edges of the gear slot icons on your character sheet and in the Inspect window.", "Mostra a durabilidade total do seu equipamento sobre o modelo do personagem, movida pelos dois deslocamentos, e recorta as bordas dos ícones de espaço na sua ficha e na janela de inspeção.")
T("Shows up to three extra compact notices for Blizzard personal item-loot toasts. Filter by minimum quality, mount or pet items, and optionally up to 100 item IDs. Native Blizzard notices remain visible; ordinary bag additions without a toast are not included.", "Mostra até três avisos compactos adicionais para notificações de saque pessoal da Blizzard. Filtre por qualidade mínima, itens de montaria ou mascote e, opcionalmente, até 100 IDs de itens. As notificações nativas da Blizzard continuam visíveis; itens comuns colocados nas bolsas sem notificação não são incluídos.")
T("Shows whichever haste buff is active, from any source: Bloodlust, Heroism, Time Warp, Primal Rage, Fury of the Aspects and similar.", "Mostra o benefício de aceleração ativo, de qualquer origem: Sede de Sangue, Heroísmo, Distorção Temporal, Raiva Primeva, Fúria dos Aspectos e similares.")
T("Shows your current talent build and loot specialization on ready checks, when a dungeon queue pops, or when you enter an instance. It never changes your talents or loot spec.", "Mostra a configuração atual de talentos e a especialização de saque em verificações de prontidão, quando a fila de uma masmorra aparece ou quando você entra em uma instância. Nunca altera seus talentos nem sua especialização de saque.")
T("Shows your most recent successful spells. Standard rows have an icon, name and marker; Icons only is a compact vertical icon column. Display width applies to standard rows; icon width follows row height in the icon preset. Position and anchor are set in MSUF Edit Mode, which shows sample actions. The list stops listening while disabled. Spells whose details the client keeps private cannot appear.", "Mostra os feitiços bem-sucedidos mais recentes. As linhas padrão têm ícone, nome e marcador; Apenas ícones exibe uma coluna vertical compacta. A largura configurada vale para as linhas padrão; no visual Apenas ícones, a largura acompanha a altura da linha. Defina posição e âncora no Modo de Edição do MSUF, que mostra ações de exemplo. A lista deixa de acompanhar feitiços quando desativada. Feitiços cujos detalhes o cliente mantém privados não aparecem.")
T("Shows your own Bloodlust exhaustion while in a group, or a ready state if you prefer. Relevant player aura changes update it; MSUF Edit Mode moves it and previews the locked state.", "Mostra sua própria exaustão de Bloodlust enquanto estiver em grupo ou em estado de prontidão, se preferir. Mudanças relevantes na aura do jogador a atualizam; MSUF Modo de Edição move-o e visualiza o estado bloqueado.")
