T("Silences the game sound files whose IDs you list, such as a mount or summon sound; up to 200. MSUF mutes exactly the files listed here and plays them again when you remove an ID or turn this helper off, and it leaves files muted by other addons alone. Muting works whether or not volume profiles are applied.", "Silencia até 200 arquivos de som do jogo listados por ID, como sons de montarias ou evocações. O MSUF silencia exatamente os arquivos listados e os restaura ao remover um ID ou desativar o auxiliar; preserva os silenciados por outros addons. Funciona com ou sem perfis de volume.")
T("Silences these game sound files, such as a mount or summon sound, while this helper is on. Remove an ID to hear that sound again.", "Silencia estes arquivos de som, como sons de montarias ou evocações, enquanto o auxiliar está ativo. Remova um ID para ouvi-lo novamente.")
