T("Sort applicants for your own Mythic+ listing by their average member score, highest first. Ties keep Blizzard's order. If any score is missing or restricted, the native order remains. The closed list is untouched.", "Ordena os candidatos ao seu grupo de Mítica+ pela pontuação média dos membros, da maior para a menor. Empates mantêm a ordem da Blizzard. Se faltar alguma pontuação ou ela estiver restrita, a ordem original permanece. A lista fechada não é alterada.")
