T("Switch between native tabs, combined bank, combined warbank and shared categories with the button below the bank window. Shared categories include accessible character and warbank tabs. Manage bank tabs returns to Blizzard purchases, deposits and tab settings. The bank views have the same smart search, free slot count and collapsible category headers. Every slot keeps its own item action and bank stacks are never merged; clicking a warband item selects Blizzard's Warband Bank tab first, and a refundable item asks before it enters the warband bank.", "Alterne entre abas nativas, banco combinado, banco do bando combinado e categorias compartilhadas pelo botão abaixo do banco. Categorias compartilhadas incluem abas acessíveis do personagem e do bando. Gerenciar abas volta às compras, depósitos e configurações da Blizzard. As visualizações têm a mesma busca inteligente, contagem de espaços livres e cabeçalhos recolhíveis. Cada espaço mantém sua ação e as pilhas do banco nunca são combinadas; clicar em um item do bando seleciona primeiro a aba Banco do Bando da Blizzard, e itens reembolsáveis pedem confirmação antes de entrar nele.")
T("Switch each bar on or off here. Turning it back on restores its previous visibility mode. Select Layout to customize the bar selected above.", "Ative ou desative cada barra aqui. Ao ativá-la, o modo de visibilidade anterior é restaurado. Selecione Layout para personalizar a barra escolhida acima.")
T("Switch on the first option, then keep or drop the reminders you want. A reminder shows only when your character knows its spell. Stances, auras, shields, Shadowform and weapon or shield imbues show while they are missing. Buffs you put on an ally (Source of Magic, Blistering Scales, Earth Shield, Symbiotic Relationship) show while your buff is on nobody in the group; target an ally and click the icon to cast it. Right-click or middle-click any reminder to hide it until you reload the UI.", "Ative a primeira opção e depois mantenha ou desative os lembretes desejados. Um lembrete só aparece se seu personagem conhece o feitiço. Posturas, auras, escudos, Forma de Sombra e encantamentos de arma ou escudo aparecem quando faltam. Benefícios aplicados a um aliado (Fonte de Magia, Escamas Virulentas, Escudo da Terra, Relação Simbiótica) aparecem enquanto ninguém do grupo tiver seu benefício; selecione um aliado e clique no ícone para lançar. Clique com o botão direito ou do meio em um lembrete para ocultá-lo até recarregar a interface.")
