T("Type /keys or /msufkeys to see your own current keystone. Add party, raid or instance to share it in that channel. /keys group requests keys from group members running this Suite helper. The /keys alias is used only when another addon has not claimed it. Inside dungeons and raids Blizzard locks chat for addons; your key is then shown only to you.", "Digite /keys ou /msufkeys para ver sua pedra-chave atual. Adicione party, raid ou instance para compartilhá-la nesse canal. /keys group pede as pedras dos membros do grupo que usam este assistente do Suite. O atalho /keys só é usado se nenhum outro addon o tiver registrado. Dentro de masmorras e raides a Blizzard bloqueia o bate-papo para addons; sua pedra-chave então é mostrada só para você.")
T("Type /msufguildprivacy or use the small ON/OFF button above the main chat window. Any chat window containing Guild or Officer is covered in full, including other channels in a mixed window. The guild chat in the Guild & Communities window can be covered as well; other communities stay visible. Reveal the chat again with the click chosen here. Messages keep arriving underneath.", "Digite /msufguildprivacy ou use o pequeno botão ON/OFF acima da janela principal do chat. Qualquer janela de bate-papo contendo Guilda ou Oficial é coberta integralmente, incluindo outros canais em uma janela mista. O bate-papo da guilda na janela Guilda e Comunidades também pode ser coberto; as outras comunidades continuam visíveis. Mostre o bate-papo de novo com o clique escolhido aqui. As mensagens continuam chegando por baixo.")
T("Type /msufraid to expand Blizzard's Raid Manager, /msufpull [1-60] for its native countdown, or /msufmark tank or /msufmark healer to mark one unambiguous party member. Optional automatic markers work only for one clear tank or healer in a five-player party, as leader or assistant. Existing and occupied markers are respected. Countdowns, markers and ready checks wait while Blizzard restricts them during combat, encounters and keystones; automatic markers try again afterwards.", "Digite /msufraid para expandir o gerenciador de raide da Blizzard, /msufpull [1-60] para a contagem regressiva nativa, ou /msufmark tank ou /msufmark healer para marcar um único membro do grupo sem ambiguidade. As marcas automáticas opcionais funcionam apenas para um tanque ou curador inequívoco em um grupo de cinco, como líder ou assistente. Marcas existentes e ocupadas são respeitadas. Contagens, marcas e verificações de prontidão aguardam enquanto a Blizzard as restringe em combate, encontros e pedras-chave; as marcas automáticas tentam de novo depois.")
T("Type /way x y for the current map or /way mapID x y. /msufway always works. The short /way alias is used only when no other addon owns it.", "Digite /way x y para o mapa atual ou /way mapID x y. /msufway sempre funciona. O alias curto /way é usado somente quando nenhum outro complemento o possui.")
