T("Uses Blizzard's Sell All Junk action when a merchant opens, including its per-bag exclusions. Hold Shift while opening the merchant to skip selling. The optional chat line confirms the request, not completed sales.", "Usa a ação Vender Toda a Sucata da Blizzard quando um comerciante é aberto, incluindo as exclusões de cada bolsa. Segure Shift ao abrir o comerciante para não vender. A linha opcional no bate-papo confirma o pedido, não as vendas concluídas.")
