T("When BigWigs, Details or another addon provides LibKeystone or LibOpenRaid, a keys request asks it too, so players without the Suite are listed.", "Quando BigWigs, Details ou outro addon fornece LibKeystone ou LibOpenRaid, uma solicitação de chaves também o consulta, listando jogadores sem a Suite.")
T("When a dungeon queue pops", "Quando uma fila de masmorra aparece")
T("When a ready check starts outside combat and your mana as a healer is low, a short note shows how much you have; it turns red below half of your limit. Only your own mana is read.", "Quando uma verificação de prontidão começa fora de combate e sua mana de curador está baixa, uma nota curta mostra quanto você tem; ela fica vermelha abaixo da metade do seu limite. Só a sua própria mana é lida.")
T("When equipment sets exist, all equippable items are protected. Exact set membership is unavailable to this helper.", "Se houver conjuntos de equipamento, todos os itens equipáveis serão protegidos. Este auxiliar não identifica exatamente os itens de cada conjunto.")
T("When leaving", "Ao sair")
T("When someone offers you a resurrection, its dialog gets a green frame, optionally with Blizzard's ready check sound, and its accept button can get a green frame of its own. Accepting stays your click.", "Quando alguém oferece uma ressurreição, o diálogo ganha uma moldura verde, opcionalmente com o som de verificação de prontidão da Blizzard, e o botão de aceitar pode ganhar sua própria moldura verde. Aceitar continua sendo o seu clique.")
T("When the key ends", "Quando a chave termina")
T("When the native group listing panel closes with applications still active, show their count in your own chat. Your applications remain active and no group chat is sent.", "Quando o painel da busca de grupos fechar com candidaturas ainda ativas, mostre a quantidade no seu próprio chat. Suas candidaturas continuam ativas e nenhuma mensagem é enviada ao grupo.")
T("When the selected bar appears", "Quando a barra selecionada aparece")
T("When this bar shows, and how far it fades out of combat. Tooltips show a spell when you hover its icon. This page and MSUF Edit Mode always show every bar.", "Quando esta barra aparece e quanto ela esmaece fora de combate. As dicas mostram um feitiço quando você passa o mouse sobre o ícone dele. Esta página e o Modo de Edição do MSUF sempre mostram todas as barras.")
