T("Which numbers show, which one is drawn on top, and their size and place. Single spells can differ: click them in the preview. The font settings below apply to every bar; Slug has no shadow.", "Quais números aparecem, qual é desenhado por cima, além do tamanho e da posição deles. Feitiços individuais podem ser diferentes: clique neles na prévia. As configurações de fonte abaixo valem para todas as barras; Slug não tem sombra.")
T("Which units get nameplates and how plates share space.", "Quais unidades recebem placas e como elas dividem o espaço.")
T("While DataTexts and this choice are enabled, MSUF remembers this character's gold at login and after money changes. Hover a Gold or Session gold DataText to see the last known account total and up to eight other characters. No background scans are used.", "Enquanto os textos de dados e esta opção estiverem ativos, o MSUF registra o ouro do personagem ao entrar e após alterações de dinheiro. Passe o mouse sobre um texto Ouro ou Ouro da sessão para ver o último total conhecido da conta e até oito outros personagens. Nenhuma varredura em segundo plano é usada.")
T("While DataTexts is active, hide Blizzard's backpack and bag slots. A Bag space DataText opens the native bags when clicked. Turn this off to restore the Blizzard buttons.", "Enquanto os Textos informativos estiverem ativos, oculta a mochila e os espaços de bolsa da Blizzard. Um texto informativo Espaço nas bolsas abre as bolsas nativas ao ser clicado. Desative isto para restaurar os botões da Blizzard.")
T("While a key runs, each defeated boss shows how far ahead or behind you are: against the best time you ever had on that boss, or against the boss times of your fastest completed run, at this keystone level or at any. Only runs this character completed count. With target times on, bosses still alive show the time to beat.", "Durante uma chave, cada chefe derrotado mostra o quanto você está à frente ou atrás: em relação ao seu melhor tempo naquele chefe ou aos tempos dos chefes da sua corrida concluída mais rápida, neste nível de chave ou em qualquer um. Só contam as corridas concluídas por este personagem. Com os tempos-alvo ativados, os chefes ainda vivos mostram o tempo a superar.")
T("While the buff of this item's use lasts, the icon shows its duration and stacks instead of the cooldown.", "Enquanto durar o benefício do uso deste item, o ícone mostra duração e acúmulos no lugar da recarga.")
T("While the buff of this spell lasts, the icon shows its duration and stacks instead of the cooldown.", "Enquanto o bônus deste feitiço durar, o ícone mostra a duração e os acúmulos dele em vez da recarga.")
T("While this is on, move the window in MSUF Edit Mode or with the two positions below. While it is off, Blizzard's Edit Mode places it.", "Com esta opção ativa, mova a janela no Modo de Edição do MSUF ou pelas duas posições abaixo. Desativada, o Modo de Edição da Blizzard a posiciona.")
T("While you hold the key, a tooltip that the rules above would hide is shown.", "Enquanto a tecla estiver pressionada, mostra uma dica que as regras acima ocultariam.")
