T("With every selected DoT active, even a lone one, the all-DoTs color wins over individual and role colors. Otherwise individual colors follow list order.", "Com todos os DoTs selecionados ativos, mesmo um único, a cor de todos os DoTs tem prioridade sobre as cores individuais e de função. Caso contrário, as cores individuais seguem a ordem da lista.")
T("Withdraw", "Retirar")
T("WoW Forever only. Lists your group's threat on the watched enemy from Blizzard's threat data, highest first; for a friendly target, its enemy is used. Values the game keeps hidden are left out. Turn the mouse wheel over the window when more members are listed than rows fit. The red mark shows where you would take aggro, which is not the point where you match the tank. The meter repaints at most five times a second and reads no combat log.", "Somente WoW Forever. Lista a ameaça do seu grupo sobre o inimigo observado a partir dos dados de ameaça da Blizzard, da maior para a menor; para um alvo amigável, usa o inimigo dele. Valores que o jogo oculta ficam de fora. Gire a roda do mouse sobre a janela quando houver mais membros do que linhas. A marca vermelha mostra onde você puxaria a ameaça, que não é o ponto em que você iguala o tanque. O medidor redesenha no máximo cinco vezes por segundo e não lê o registro de combate.")
