T("|cff9fc3e7[Guild]|r %s: Welcome to MSUF.", "|cff9fc3e7[Guilda]|r %s: Boas-vindas ao MSUF.")
T("|cffc9d4dd[Party]|r Chat links and channels stay native.", "|cffc9d4dd[Grupo]|r Links e canais do bate-papo continuam nativos.")
T("|cffc9d4dd[Raid]|r %s: Pull when %s is ready.", "|cffc9d4dd[Raide]|r %s: Inicie quando %s estiver pronto.")
T("• No idle OnUpdate; a window corner drag runs one only while the mouse button is held\n• No repeating tickers; short one-shot timers only batch layout and hover updates\n• One frame walk per session, when the window skin is first enabled, adopts existing panel buttons\n• No aura or nameplate listeners; unit events only for the Micro Bar portrait and open character panels\n• Combat-state events only pause and resume deferred work and close open option popups\n• One shared ADDON_LOADED dispatcher only while catalog targets are pending\n• External weak-key runtime state", "• Sem OnUpdate ocioso; arrastar um canto da janela executa um só enquanto o botão do mouse estiver pressionado\n• Sem tickers repetitivos; temporizadores curtos de uso único só agrupam atualizações de layout e de passar o mouse\n• Uma varredura de quadros por sessão, quando a skin de janelas é ativada pela primeira vez, adota os botões de painel existentes\n• Sem ouvintes de auras ou placas de nome; eventos de unidade só para o retrato da microbarra e os painéis de personagem abertos\n• Eventos de estado de combate só pausam e retomam o trabalho adiado e fecham pop-ups de opções abertos\n• Um único despachante ADDON_LOADED compartilhado só enquanto houver alvos do catálogo pendentes\n• Estado de execução externo com chaves fracas")
